import { Box, Column, Image, Path, Root, Row, Text, formatColor, mixColor, parseColor } from '../index.js'
import type { Gradient } from '../index.js'
import { writeFileSync } from 'node:fs'

/** `color.ts, parseColor`. */
export async function example_parseColor(): Promise<void> {

  const from = parseColor('#f2aa4c')
  const to = parseColor('rebeccapurple')
  if (from && to) formatColor(mixColor(from, to, 0.5))
}

/** `node.ts`. */
export async function example_node(): Promise<void> {

  const card = Row({
    gap: 16,
    padding: 24,
    backgroundColor: '#101014',
    children: [Text('Ukasyah', { fontSize: 24, fontWeight: 'bold' })],
  })
}

/** `node.ts, Text`. */
export async function example_Text(): Promise<void> {

  const name = Text('Ukasyah', { fontSize: 24 })
}

/** `node.ts, Image`. */
export async function example_Image(): Promise<void> {

  const avatar = Image({ src: 'avatar.png', width: 64, height: 64, objectFit: 'cover' })
}

/** `node.ts, Path`. */
export async function example_Path(): Promise<void> {

  const tick = Path({ d: 'M2 8 L6 12 L14 3' })
}

/** `root.ts, FontRegistration`. */
export async function example_FontRegistration(): Promise<void> {
  // Register once, where the process starts.
  const FONTS = [{ family: 'Brand', paths: ['./fonts/Brand-Regular.ttf'] }]
  const canvas = await Root({ width: 200, height: 100, fonts: FONTS, children: [] })
  canvas.release()
}

/** `root.ts, Root`. */
export async function example_Root(): Promise<void> {

  const canvas = await Root({
    width: 520,
    height: 180,
    backgroundColor: '#101014',
    children: Row({ padding: 24, children: Text('Ukasyah', { fontSize: 26 }) }),
  })

  await canvas.toFile('card.png')
}

/** `style.ts, Gradient`. */
export async function example_Gradient(): Promise<void> {

  const fade: Gradient = { type: 'linear', direction: 'to-bottom', colors: ['#101014', 'transparent'] }
  const dial: Gradient = { type: 'conic', from: 90, stops: [{ offset: 0, color: '#f0c' }] }
}

/** `README.md`. */
export async function example_README_md(): Promise<void> {

  const canvas = await Root({
    width: 320,
    padding: 20,
    backgroundColor: '#101820',
    children: Column({
      gap: 10,
      children: [
        Text('meo-canvas', { fontSize: 22, fontWeight: 600, color: '#f2aa4c' }),
        Text('Describe a layout; get image bytes back.', { fontSize: 13, color: '#c8ccd4' }),
        Box({ height: 4, width: 64, backgroundColor: '#f2aa4c', borderRadius: 2 }),
      ],
    }),
  })

  writeFileSync('card.png', await canvas.toBuffer('png'))
  canvas.release()
}

/** `README.md`. */
export async function example_README_md_2(): Promise<void> {

  const children = [Box({ height: 40, backgroundColor: '#f2aa4c' })]

  Root({ width: 520, children }) // as tall as the content
  Root({ width: 520, minHeight: 200, children }) // ...and at least 200
  Root({ width: 520, height: 180, children }) // exactly 180
}

/** `README.md`. */
export async function example_README_md_3(): Promise<void> {

  const FONTS = [{ family: 'Brand', paths: ['./fonts/Brand-Regular.ttf', './fonts/Brand-Bold.ttf'] }]

  const canvas = await Root({
    width: 600,
    height: 400,
    fonts: FONTS,
    children: [Text('Hello', { fontFamily: 'Brand', fontSize: 24 })],
  })
  canvas.release()
}

